/**
 * Loading placeholder that holds the layout while content arrives (`design/components/skeleton.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/skeleton.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, createDerived, type Defaults, type SpaceStep } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/skeleton.module.css'

export type SkeletonShape = NonNullable<SkeletonProps['shape']>

export interface SkeletonProps {
  /**
   * Set when the skeleton stands for a named region; makes the root a `role="status"` with this
   * name. Otherwise it is hidden, because a grey box means nothing to a screen reader.
   */
  label?: string
  shape?: 'text' | 'rect' | 'circle'
  size?: SpaceStep
  /**
   * The step whose line box this stands in for.
   */
  textStep?: 'sm' | 'md' | 'lg' | 'xs' | 'xl' | '2xl' | '3xl'
  /**
   * A space step, or the full width of whatever holds it.
   */
  width?: SpaceStep | 'full'
}

/** Loading placeholder that holds the layout while content arrives. */
export default function Skeleton(given: SkeletonProps): JSX.Element {
  const props = mergeProps({ shape: 'text' } as Defaults<SkeletonProps, 'shape'>, claimSlot(given))
  const step = createDerived(() => (props.shape === 'text' ? (props.textStep ?? 'md') : undefined))
  const span = createDerived(() => (props.shape === 'circle' ? undefined : (props.width ?? 'full')))
  const named = createDerived(() => props.label !== undefined)
  return (
    <div
      class={styles.skeleton}
      data-shape={props.shape}
      data-text-step={step.value}
      data-width={span.value === undefined ? undefined : String(span.value)}
      data-size={props.size === undefined ? undefined : String(props.size)}
      role={named.value ? 'status' : undefined}
      aria-label={props.label}
      aria-hidden={!named.value ? true : undefined}
      data-member="skeleton"
    />
  )
}
